const PEOPLE = Array.from({ length: 87 }, (_, i) => ({
  name: `Person ${i + 1}`,
  age: 20 + ((i * 7) % 50),
}));

const PageSizeTemplate = () => {
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);
  const rows = PEOPLE.slice((page - 1) * pageSize, page * pageSize);
  return (
    <Flex
      css={{ backgroundColor: "$bg02", minHeight: "100vh", padding: "$xl" }}
    >
      <TableV3.PaginationWrapper
        currentPage={page}
        totalCount={PEOPLE.length}
        dataLength={rows.length}
        totalPages={Math.ceil(PEOPLE.length / pageSize)}
        onPageChange={setPage}
        pageSize={pageSize}
        pageSizeOptions={[10, 20, 50, 100]}
        onPageSizeChange={(size) => {
          setPageSize(size);
          setPage(1);
        }}
      >
        <TableV3.Root>
          <TableV3.Head>
            <TableV3.Header>Name</TableV3.Header>
            <TableV3.Header>Age</TableV3.Header>
          </TableV3.Head>
          <TableV3.Body>
            {rows.map((row) => (
              <TableV3.Row key={row.name}>
                <TableV3.Cell>{row.name}</TableV3.Cell>
                <TableV3.Cell>{row.age}</TableV3.Cell>
              </TableV3.Row>
            ))}
          </TableV3.Body>
        </TableV3.Root>
      </TableV3.PaginationWrapper>
    </Flex>
  );
};

/** Rows-per-page picker (pageSize, pageSizeOptions, onPageSizeChange). */
export const WithPageSize: Story = {
  render: () => <PageSizeTemplate />,
};
